/*
 * prog19_palindrome_checker.c
 *
 * Re‑implementation of the original binary’s observable behaviour.
 *
 * Behaviour:
 *   - If an argument is supplied, it is taken as the input string.
 *   - If the input length exceeds 1024 characters, the program prints
 *       "TOO_LONG" and exits.
 *   - Otherwise the string is *normalised*:
 *         * all characters that are not alphanumeric are discarded,
 *         * remaining characters are converted to lower‑case.
 *   - The normalised string is tested for being a palindrome.
 *   * If it is a palindrome the program prints "PALINDROME",
 *   * otherwise it prints "NOT_PALINDROME".
 *   - When no argument is supplied the program treats the input as an
 *     empty string, which is considered a palindrome, and therefore
 *     prints "PALINDROME".
 *
 * The implementation follows the logic uncovered in the disassembly,
 * but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_LEN 1024

int main(int argc, char *argv[])
{
    const char *input;
    size_t i, len, norm_len = 0;
    char norm[MAX_LEN + 1];          /* normalised string (max 1024) */

    /* -------------------------------------------------------------
     *  1. Obtain the input string.
     * ------------------------------------------------------------- */
    if (argc > 1) {
        input = argv[1];
    } else {
        /* No argument – treat as empty string (original binary does this). */
        input = "";
    }

    /* -------------------------------------------------------------
     *  2. Length check (original binary used the raw length, not the
     *     normalised one).
     * ------------------------------------------------------------- */
    len = strlen(input);
    if (len > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* -------------------------------------------------------------
     *  3. Normalise: keep only alphanumeric characters, convert to lower.
     * ------------------------------------------------------------- */
    for (i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            if (norm_len >= MAX_LEN)   /* safety – should never happen */
                break;
            norm[norm_len++] = (char)tolower(c);
        }
    }
    norm[norm_len] = '\0';

    /* -------------------------------------------------------------
     *  4. Palindrome test on the normalised string.
     * ------------------------------------------------------------- */
    int is_pal = 1;
    for (i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    /* -------------------------------------------------------------
     *  5. Output the result.
     * ------------------------------------------------------------- */
    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
